What does the following code output?
#include <iostream>
using namespace std;
void increment(int arr[], int size) {
for(int i=0;i<size;i++)
(*(arr+i))++;
}
int main() {
int data[3] = {2,4,6};
increment(data,3);
cout << data[0] << " " << data[1] << " " << data[2];
return 0;
}

